import type {SidebarsConfig} from '@docusaurus/plugin-content-docs';
import registry from './src/data/leagues.json';

// A league entry: a clickable category whose link is the generated landing page
// (docs/docs/{prefix}/index.md) and whose children are the auto-generated
// reference subtree (reference/{api}.md + loaders.md). The reference pages are
// regenerated from endpoint metadata by `python tools/codegen/generate.py --docs`
// and ordered/labelled via the generated _category_.json + page frontmatter, so
// new endpoints surface in the nav with no sidebar edit. Only adding a whole new
// LEAGUE needs a line in tools/codegen/generate.py's registry (see `sports` below).
function league(prefix: string, label: string) {
  return {
    type: 'category' as const,
    label,
    link: {type: 'doc' as const, id: `${prefix}/index`},
    items: [{type: 'autogenerated' as const, dirName: `${prefix}/reference`}],
  };
}

type League = {prefix: string; label: string; group?: string};

// A sport's leagues: those without a `group` first (the headline leagues), then one collapsed
// sub-category per group in the order the registry lists it. A group of one league is listed
// directly. The groups come from `_LEAGUE_GROUPS` in tools/codegen/generate.py, never from here.
function sportItems(leagues: League[]) {
  const items: ReturnType<typeof league | typeof subgroup>[] = [];
  const groups = new Map<string, League[]>();
  for (const l of leagues) {
    if (!l.group) items.push(league(l.prefix, l.label));
    else groups.set(l.group, [...(groups.get(l.group) ?? []), l]);
  }
  for (const [label, members] of groups) {
    items.push(members.length === 1 ? league(members[0].prefix, members[0].label) : subgroup(label, members));
  }
  return items;
}

function subgroup(label: string, members: League[]) {
  return {
    type: 'category' as const,
    label,
    collapsed: true,
    items: members.map((l) => league(l.prefix, l.label)),
  };
}

// Every league the codegen documents, under its sport: docs/src/data/leagues.json, written by
// tools/codegen/generate.py from leagues.yaml and the other generated league directories. A sport opens a
// generated page of its leagues (under /docs/leagues/, so it never collides with a league such as soccer),
// which also gives the breadcrumb "Football" a link.
const sports = registry.sports.map((sport) => ({
  type: 'category' as const,
  label: sport.label,
  link: {
    type: 'generated-index' as const,
    title: sport.label,
    slug: `/leagues/${sport.key}`,
    description: `The ${sport.label.toLowerCase()} leagues in sdv-py: each opens its endpoint reference, dataset loaders and R parity table.`,
  },
  items: sportItems(sport.leagues as League[]),
}));

